/**
 * Scratch W3 egress SOCKS5 server (egress-a / egress-b containers).
 *
 * Fixed-source-IP exit: every outbound dial originates from this container's
 * ladder IP (172.38.222.50 / .51) — the private analog of a real proxy
 * provider's exit IP. D6 drift simulation: DIAL_VIA=<ip:port> routes each
 * connection through the egress-c dialer (172.38.222.53) so the same proxy
 * address/credentials exit from a DIFFERENT IP (true drift, ADR-027 D6).
 *
 * Protocol: SOCKS5, method 02 (username/password) — the credential pair is
 * the D10 canary fixture (generated by w3-bringup, never a real credential).
 * Conn log: /logs/egress-conn.jsonl (ts/dst/via — zero credentials).
 *
 * NOTE: socket reader must carry over bytes between reads (curl sends
 * greeting+auth in one segment — naive per-read buffers drop the tail).
 */
import net from 'node:net';
import fs from 'node:fs';

const PORT = Number(process.env.PORT ?? 1080);
const USER = process.env.EGRESS_USER ?? '';
const PASS = process.env.EGRESS_PASS ?? '';
const DIAL_VIA = process.env.DIAL_VIA ?? ''; // "ip:port" relay (drift sim)
const LOG = '/logs/egress-conn.jsonl';
try { fs.mkdirSync('/logs', { recursive: true }); } catch {}

const log = (o) => { try { fs.appendFileSync(LOG, JSON.stringify({ ts: new Date().toISOString(), ...o }) + '\n'); } catch {} };

class Reader {
  constructor(sock) {
    this.buf = Buffer.alloc(0);
    this.waiters = [];
    sock.on('data', (d) => {
      this.buf = Buffer.concat([this.buf, d]);
      this.pump();
    });
    sock.once('error', () => this.fail(new Error('socket error')));
    sock.once('close', () => this.fail(new Error('socket closed')));
  }
  pump() {
    for (let i = 0; i < this.waiters.length; i++) {
      const w = this.waiters[i];
      if (this.buf.length >= w.n) {
        const out = this.buf.subarray(0, w.n);
        this.buf = this.buf.subarray(w.n);
        this.waiters.splice(i, 1);
        i--;
        w.res(out);
      } else break;
    }
  }
  read(n) {
    if (this.buf.length >= n) {
      const out = this.buf.subarray(0, n);
      this.buf = this.buf.subarray(n);
      return Promise.resolve(out);
    }
    return new Promise((res, rej) => this.waiters.push({ n, res, rej }));
  }
  fail(err) { this.waiters.splice(0).forEach((w) => w.rej(err)); }
}

function parseDst(req) {
  const atyp = req[3];
  let host, port, off = 4;
  if (atyp === 1) { host = `${req[off]}.${req[off + 1]}.${req[off + 2]}.${req[off + 3]}`; off += 4; }
  else if (atyp === 3) { const len = req[off]; host = req.subarray(off + 1, off + 1 + len).toString('utf8'); off += 1 + len; }
  else if (atyp === 4) { const b = req.subarray(off, off + 16); host = [...b].map((x, i) => (i % 2 ? x : 0)).reduce((h, x, i) => (i % 2 === 0 ? h + (x << 8) : h + x), 0).toString(16); off += 16; }
  else throw new Error(`bad atyp ${atyp}`);
  port = req[off] * 256 + req[off + 1];
  return { host, port };
}

function pipe(a, b) { a.pipe(b); b.pipe(a); }

const srv = net.createServer((sock) => {
  const r = new Reader(sock);
  let dstStr = '?';
  (async () => {
    const g = await r.read(2);
    if (g[0] !== 5) { sock.end(); return; }
    const nmethods = g[1];
    if (nmethods > 0) await r.read(nmethods); // consume method list (we require user/pass)
    sock.write(Buffer.from([5, 2])); // require user/pass
    const vn = (await r.read(1))[0]; // 1 per RFC 1929
    const ulen = (await r.read(1))[0];
    const user = (await r.read(ulen)).toString('utf8');
    const plen = (await r.read(1))[0];
    const pass = (await r.read(plen)).toString('utf8');
    const authOk = USER && PASS && user === USER && pass === PASS;
    sock.write(Buffer.from([1, authOk ? 0 : 1]));
    if (!authOk) { log({ auth: 'FAIL' }); sock.end(); return; }
    const head4 = await r.read(4);
    const atyp = head4[3];
    let rest;
    if (atyp === 1) rest = await r.read(6); // 4 ip + 2 port
    else if (atyp === 3) {
      const lenByte = await r.read(1);
      rest = Buffer.concat([lenByte, await r.read(lenByte[0] + 2)]); // len + name + 2 port
    }
    else if (atyp === 4) rest = await r.read(18); // 16 ip + 2 port
    else throw new Error(`bad atyp ${atyp}`);
    const req = Buffer.concat([head4, rest]);
    const { host, port } = parseDst(req);
    dstStr = `${host}:${port}`;
    let out;
    if (DIAL_VIA) {
      const [rip, rport] = DIAL_VIA.split(':');
      out = await net.connect(Number(rport), rip);
      out.write(`${host} ${port}\n`);
    } else {
      out = await net.connect(port, host);
    }
    // reply mirrors the request address type (libcurl 8.x is strict about it)
    let reply;
    if (atyp === 3) {
      const hb = Buffer.from(host);
      reply = Buffer.concat([Buffer.from([5, 0, 0, 3, hb.length]), hb, Buffer.from([port >> 8, port & 0xff])]);
    } else if (atyp === 1) {
      reply = Buffer.from([5, 0, 0, 1, 0, 0, 0, 0, port >> 8, port & 0xff]);
    } else {
      reply = Buffer.concat([Buffer.from([5, 0, 0, 4]), Buffer.alloc(16), Buffer.from([port >> 8, port & 0xff])]);
    }
    sock.write(reply);
    log({ dst: dstStr, via: DIAL_VIA || 'direct' });
    pipe(sock, out);
  })().catch((e) => {
    log({ dst: dstStr, err: String(e.message).slice(0, 120) });
    sock.end();
  });
});
srv.listen(PORT, '0.0.0.0', () => console.log(`[rdev-egress] socks5 :${PORT} via=${DIAL_VIA || 'direct'}`));
